installer-gui-script.script:
function ggCheck() {
    var code = system.run('check.sh');
    if (code == 0) return true;
    var messages = {
        1: 'This Mac is not running macOS 26.6 (25G72).',
        2: 'Golden Gate Glass requires an Intel Mac.',
        3: 'System Integrity Protection (filesystem) must be disabled.',
        4: 'AMFI must be disabled (amfi_get_out_of_my_way=1 in boot-args).'
    };
    my.result.type = 'Fatal';
    my.result.title = 'Golden Gate Glass cannot be installed';
    my.result.message = messages[code] || 'Could not check this Mac.';
    return false;
}
